//! Bounded capital allocation over actual certified sources. Never execution authority.
//! ReadHint is NOT an Admission, reservation, released cash or dispatch permit.
use crate::{authority::Activation,feedback::Result,package_admission::{self,Admission},package_portfolio::{self,Plan},relationship_strategy::{CertifiedComponent,Policy}};
use baal_transport_service::{Receipt,relationships,decimal_units};
use moloch_replay::{session::Session,Side as NativeSide};
use moloch_relationship_arbitrage::{Limits,Side,UNIT};
use serde::{Serialize,Deserialize};
use serde_json::{Value,json};
use sha2::{Digest,Sha256};
use std::collections::{BTreeMap,BTreeSet};
fn need(b:bool,s:&'static str)->Result<()>{if b{Ok(())}else{Err(s.into())}}
fn sha<T:Serialize>(v:&T)->Result<String>{Ok(format!("{:x}",Sha256::digest(serde_json::to_vec(v)?)))}
fn dec(v:&Value)->Result<i128>{Ok(decimal_units(v.as_str().ok_or("ALLOCATION_DECIMAL")?)?)}
fn add(a:i128,b:i128)->Result<i128>{a.checked_add(b).ok_or_else(||"ALLOCATION_RANGE".into())}
fn sub(a:i128,b:i128)->Result<i128>{a.checked_sub(b).ok_or_else(||"ALLOCATION_RANGE".into())}
fn mul(a:i128,b:i128)->Result<i128>{a.checked_mul(b).ok_or_else(||"ALLOCATION_RANGE".into())}
fn hex(s:&str)->bool{s.len()==64&&s.bytes().all(|b|b.is_ascii_digit()||(b'a'..=b'f').contains(&b))}
/// Explicit root-reviewed policy input, not an official payoff/receipt certificate.
/// A trusted digest must come from immutable reviewed control, never self-approval.
#[derive(Clone,Serialize,Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct ReviewInput{pub certificate_sha256:String,pub risk_group:String,pub write_cost_units:i128,pub inventory_risk_units:i128,pub holding_horizon_ms:Option<u64>,pub comparable_group:Option<String>,pub expires_at_ms:u64,pub source_sha256:String}
pub struct ReviewedCosts{input:ReviewInput,sha:String}
impl ReviewedCosts{
 pub fn verify(input:ReviewInput,trusted:&BTreeSet<String>,now:u64)->Result<Self>{let hash=sha(&input)?;need(trusted.contains(&hash)&&hex(&input.certificate_sha256)&&hex(&input.source_sha256)&&input.write_cost_units>=0&&input.inventory_risk_units>=0&&now<input.expires_at_ms,"ALLOCATION_REVIEW")?;need(!input.risk_group.is_empty()&&input.risk_group.len()<=128,"ALLOCATION_RISK_GROUP")?;need(match(input.holding_horizon_ms,input.comparable_group.as_deref()){(None,None)=>true,(Some(h),Some(g))=>(1..=366*86_400_000).contains(&h)&&!g.is_empty()&&g.len()<=128,_=>false},"ALLOCATION_HORIZON")?;Ok(Self{input,sha:hash})}
 pub fn digest(input:&ReviewInput)->Result<String>{sha(input)}
 fn for_certificate(&self,certificate:&str,now:u64)->Result<()>{need(self.input.certificate_sha256==certificate&&now<self.input.expires_at_ms,"ALLOCATION_REVIEW_BINDING")}
}
/// Pinned by the root's immutable Control, never populated by a discovery
/// result. Missing or expired review withholds a candidate rather than inventing
/// zero costs, a horizon or an approval. No serde defaults hide missing fields.
#[derive(Clone,Serialize,Deserialize)]#[serde(rename_all="camelCase",deny_unknown_fields)]
pub struct Settings{pub reviews:Vec<ReviewInput>,pub trusted_review_sha256:BTreeSet<String>,pub maximum_wait:u32}
impl Settings{
 pub fn validate(&self)->Result<()>{need(self.reviews.len()<=32&&self.trusted_review_sha256.len()<=32&&(1..=32).contains(&self.maximum_wait),"ALLOCATION_SETTINGS_BOUND")?;let mut certificates=BTreeSet::new();let mut digests=BTreeSet::new();for review in &self.reviews{need(certificates.insert(review.certificate_sha256.clone()),"ALLOCATION_DUPLICATE_CERTIFICATE_REVIEW")?;let digest=ReviewedCosts::digest(review)?;need(digests.insert(digest.clone())&&self.trusted_review_sha256.contains(&digest),"ALLOCATION_CONFIGURED_REVIEW_NOT_APPROVED")?;ReviewedCosts::verify(review.clone(),&self.trusted_review_sha256,0)?;}need(digests==self.trusted_review_sha256,"ALLOCATION_UNUSED_TRUSTED_REVIEW")}
 /// Invalid overall settings cannot partially approve another configured row.
 /// Root validates configuration separately for a diagnostic; lookup withholds.
 pub fn costs_for(&self,certificate:&str,now:u64)->Option<ReviewedCosts>{self.validate().ok()?;let review=self.reviews.iter().find(|r|r.certificate_sha256==certificate)?;ReviewedCosts::verify(review.clone(),&self.trusted_review_sha256,now).ok()}
}
/// Original account cash and ACTUAL existing reservations. availableAdvance and
/// anticipated SELL proceeds never increase gross_cash or committed_capacity.
pub struct Budget{head:Value,run:Value,manifest:Value,gross_cash:i128,committed_capacity:i128,writes:u32,at:u64,valid_until:u64,cash_source:String}
impl Budget{
 pub fn from_receipt(bank:&Session,a:&Activation,cash:&Receipt,writes:u32,now:u64)->Result<Self>{let seed=bank.live_account_seed().ok_or("ALLOCATION_LIVE_BANK")?;need(!bank.engine().package_blocks_submissions()&&seed["runId"]==a.run_id&&bank.engine().policy()["maximumCommitted"]==a.maximum_committed,"ALLOCATION_BANK_SCOPE")?;let start=crate::daily_windows::clock(&cash.request_started_at)?;let end=crate::daily_windows::clock(&cash.received_at)?;need(cash.status==200&&cash.endpoint==format!("/account?tournamentId={}",a.tournament_id)&&start<=end&&end<=now&&now-start<=20_000&&writes<=24,"ALLOCATION_CASH_SOURCE")?;let scope=baal_transport_service::Scope{tournament_id:a.tournament_id.clone(),tournament_slug:a.tournament_slug.clone(),exchanges:BTreeMap::new()};let official=relationships::parse_buying_power(&cash.data,&scope)?.gross_cash_units.ok_or("ALLOCATION_CASH_UNKNOWN")?;let report=bank.engine().report()?;let reserved=dec(&report["reservedCash"])?;let gross=sub(official.min(bank.engine().wallet.cash),reserved)?;let capacity=sub(sub(decimal_units(&a.maximum_committed)?,dec(&report["ownedCost"])?)?,reserved)?;need(gross>=0&&capacity>=0,"ALLOCATION_EXISTING_RESERVATIONS")?;Ok(Self{head:bank.durable_head(),run:seed["runId"].clone(),manifest:bank.manifest_hash().clone(),gross_cash:gross,committed_capacity:capacity,writes,at:now,valid_until:start.checked_add(20_000).ok_or("ALLOCATION_CLOCK")?,cash_source:sha(cash)?})}
 fn current(&self,bank:&Session,now:u64)->Result<()>{need(now>=self.at&&now<=self.valid_until&&bank.durable_head()==self.head&&bank.manifest_hash()==&self.manifest&&bank.live_account_seed().is_some_and(|s|s["runId"]==self.run),"ALLOCATION_BANK_CHANGED_OR_EXPIRED")}
 pub fn available_gross_cash(&self)->i128{self.gross_cash}pub fn available_committed_capacity(&self)->i128{self.committed_capacity}
}
#[derive(Clone,Serialize,PartialEq,Eq,Debug)]pub enum Objective{CapitalEfficiencyOnly,ReviewedCapitalTime{comparable_group:String},CoveredUnwindStatewiseCashGain}
#[derive(Clone)]struct Metric{key:String,source:String,review:String,gain:i128,gross:i128,capital:i128,horizon:Option<u64>,group:Option<String>,risk:String,expires:u64,unwind:bool}
impl Metric{fn objective(&self)->Objective{if self.unwind{Objective::CoveredUnwindStatewiseCashGain}else if let Some(g)=&self.group{Objective::ReviewedCapitalTime{comparable_group:g.clone()}}else{Objective::CapitalEfficiencyOnly}}}
fn metric(certificate:&str,mode:&str,source:String,delta:i128,gross:i128,capital:i128,expiry:u64,costs:&ReviewedCosts,now:u64,unwind:bool)->Result<Metric>{costs.for_certificate(certificate,now)?;let gain=sub(sub(delta,costs.input.write_cost_units)?,costs.input.inventory_risk_units)?;need(gain>0&&gross>=0&&capital>=gross&&now<expiry,"ALLOCATION_NO_INCREMENTAL_EDGE")?;need(!unwind||gross==0,"ALLOCATION_UNWIND_FUNDING")?;Ok(Metric{key:format!("{certificate}:{mode}"),source,review:costs.sha.clone(),gain,gross,capital,horizon:costs.input.holding_horizon_ms,group:costs.input.comparable_group.clone(),risk:costs.input.risk_group.clone(),expires:expiry.min(costs.input.expires_at_ms),unwind})}
/// Read scheduling only. Quotes may exist, but their reservations are NEVER
/// pretended released. This object cannot be passed to package stage/send APIs.
pub struct ReadHint{metric:Metric,head:Value,relationship:String,certificate:String}
impl ReadHint{
 pub fn key(&self)->&str{&self.metric.key}pub fn relationship_id(&self)->&str{&self.relationship}pub fn certificate_sha256(&self)->&str{&self.certificate}pub fn gross_funding(&self)->i128{self.metric.gross}pub fn minimum_incremental_gain(&self)->i128{self.metric.gain}
 pub fn scan(bank:&Session,a:&Activation,c:&CertifiedComponent,p:&Policy,b:&Budget,costs:&ReviewedCosts)->Result<Option<Self>>{b.current(bank,p.now_ms)?;need(c.scope().tournament_id==a.tournament_id&&c.scope().tournament_slug==a.tournament_slug&&p.now_ms>=c.validated_at_ms()&&p.now_ms<c.expires_at_ms()&&p.quantities.len()<=32&&p.maximum_retained_candidates<=32&&(2..=3).contains(&c.compiled().contracts().len())&&bank.engine().policy()["entriesEnabled"]==true&&crate::daily_windows::clock(bank.engine().policy()["entryStopAt"].as_str().ok_or("ALLOCATION_ENTRY_CLOCK")?)?>p.now_ms&&p.entry_fee_per_share_per_leg==0&&bank.engine().policy()["feeBps"]==0&&dec(&bank.engine().policy()["feePerShare"])?==0,"ALLOCATION_COMPONENT")?;costs.for_certificate(c.certificate_sha256(),p.now_ms)?;let(books,_)=package_admission::native_books(bank,c.scope(),p.now_ms,p.max_book_age_ms.min(10_000))?;let ordered=c.compiled().contracts().iter().map(|contract|books.get(&contract.exchange_id).cloned().ok_or("ALLOCATION_BOOK_MISSING")).collect::<std::result::Result<Vec<_>,_>>()?;let cap=b.gross_cash.min(b.committed_capacity);let limits=Limits{now_ms:p.now_ms,max_book_age_ms:p.max_book_age_ms.min(10_000),max_book_skew_ms:p.max_book_skew_ms,cash_available:cap,max_package_cost:cap,max_orphan_cash_loss:cap,fee_per_share_per_leg:0,buffer_per_share:p.buffer_per_share,minimum_surplus:p.minimum_surplus,max_quantity:p.maximum_quantity};let mut best:Option<Metric>=None;
 for candidate in c.compiled().scan(&p.quantities,&ordered,&limits)?{let mut gross=0i128;let mut qty=0u64;let mut valid=true;let mut expiry=c.expires_at_ms().min(b.valid_until);for instrument in &candidate.instruments{let contract=&c.compiled().contracts()[instrument.contract];let native=if instrument.side==Side::Yes{NativeSide::No}else{NativeSide::Yes};if bank.engine().wallet.quantity(&contract.exchange_id,native)>0{valid=false;break}let book=&books[&contract.exchange_id];let levels=if instrument.side==Side::Yes{&book.yes_asks}else{&book.no_asks};let mut left=candidate.quantity;let mut limit=None;for l in levels{left=left.saturating_sub(l.quantity);if left==0{limit=Some(l.price);break}}let price=limit.ok_or("ALLOCATION_DEPTH")?;if !(5000..=995000).contains(&price)||price%5000!=0{valid=false;break}let cost=mul(price,candidate.quantity as i128)?;if add(bank.engine().wallet.market_cost(&contract.exchange_id),cost)?>decimal_units(&a.maximum_market_cost)?{valid=false;break}gross=add(gross,cost)?;qty=qty.checked_add(candidate.quantity).ok_or("ALLOCATION_RANGE")?;expiry=expiry.min(book.observed_ms.checked_add(p.max_book_age_ms.min(10_000)).ok_or("ALLOCATION_CLOCK")?).min(book.source.received_ms.checked_add(p.max_book_age_ms.min(10_000)).ok_or("ALLOCATION_CLOCK")?);}
 if !valid||qty>a.maximum_quantity as u64||gross>cap{continue}let additions=candidate.instruments.iter().map(|i|(*i,candidate.quantity)).collect::<Vec<_>>();let floor=c.compiled().portfolio_floor(&additions)?;let delta=sub(sub(floor,gross)?,candidate.buffer)?;let Ok(m)=metric(c.certificate_sha256(),"buy",sha(&json!({"component":c.source_binding(),"bankHead":b.head,"cashSource":b.cash_source,"instruments":candidate.instruments.iter().map(|i|json!([i.contract,if i.side==Side::Yes{"YES"}else{"NO"}])).collect::<Vec<_>>(),"quantity":candidate.quantity,"books":candidate.book_sources.iter().map(|s|&s.sha256).collect::<Vec<_>>(),"fullWireGross":gross} ))?,delta,gross,gross,expiry,costs,p.now_ms,false)else{continue};if let Some(old)=&best{if better(&m,old,true)?{best=Some(m)}}else{best=Some(m)}
 }Ok(best.map(|metric|Self{metric,head:b.head.clone(),relationship:c.relationship_id().into(),certificate:c.certificate_sha256().into()}))}
}
/// Borrowed opaque financial proposal. No Deserialize or caller numeric proof.
pub enum BorrowedPlan<'a>{Admission(&'a Admission),Portfolio(&'a Plan)}
pub struct Eligible<'a>{plan:BorrowedPlan<'a>,metric:Metric,head:Value}
impl<'a> Eligible<'a>{
 pub fn portfolio(bank:&Session,plan:&'a Plan,b:&Budget,costs:&ReviewedCosts,now:u64)->Result<Self>{b.current(bank,now)?;plan.validate_bank(bank,now)?;let proof=plan.proof();need(proof["runId"]==b.run&&proof["bankManifestHash"]==b.manifest,"ALLOCATION_PLAN_SCOPE")?;let certificate=proof["component"]["certificateSha256"].as_str().ok_or("ALLOCATION_CERTIFICATE")?;let unwind=plan.mode()==package_portfolio::Mode::WholeUnwind;let m=metric(certificate,if unwind{"unwind"}else{"buy"},sha(proof)?,plan.minimum_statewise_delta(),plan.gross_funding(),plan.gross_funding(),plan.expires_at_ms().min(b.valid_until),costs,now,unwind)?;Ok(Self{plan:BorrowedPlan::Portfolio(plan),metric:m,head:b.head.clone()})}
 pub fn admission(bank:&Session,plan:&'a Admission,b:&Budget,costs:&ReviewedCosts,now:u64)->Result<Self>{b.current(bank,now)?;let proof=plan.proof();need(proof["runId"]==b.run&&proof["bankManifestHash"]==b.manifest&&sha(proof)?==plan.proof_hash()&&now<plan.expires_at_ms(),"ALLOCATION_ADMISSION_SCOPE")?;let mut gross=0;let books=bank.engine().live_package_books();for l in plan.reserve_event()["legs"].as_array().ok_or("ALLOCATION_LEGS")?{let ex=l["exchangeId"].as_str().ok_or("ALLOCATION_LEG")?;need(bank.engine().wallet.quantity(ex,NativeSide::Yes)==0&&bank.engine().wallet.quantity(ex,NativeSide::No)==0&&!bank.engine().order_records().iter().any(|q|q["exchangeId"]==ex&&q["retired"]==false)&&books.iter().any(|r|r["exchangeId"]==ex&&sha(r).ok().as_deref()==l["bookHash"].as_str()),"ALLOCATION_ADMISSION_CHANGED")?;gross=add(gross,mul(dec(&l["limitPrice"])?,l["quantity"].as_u64().ok_or("ALLOCATION_QUANTITY")? as i128)?)?;}need(gross==dec(&proof["maximumCost"])?,"ALLOCATION_FULL_GROSS")?;let delta=sub(sub(dec(&proof["minimumPayout"])?,gross)?,dec(&proof["buffer"])?)?;let m=metric(plan.certificate_sha256(),"buy",sha(proof)?,delta,gross,gross,plan.expires_at_ms().min(b.valid_until),costs,now,false)?;Ok(Self{plan:BorrowedPlan::Admission(plan),metric:m,head:b.head.clone()})}
 pub fn plan(&self)->&BorrowedPlan<'a>{&self.plan}pub fn key(&self)->&str{&self.metric.key}
}
// Unlike a generic fallible comparator, every cross multiplication is checked.
// Per-time comparisons are ONLY meaningful inside the exact reviewed group.
fn better(a:&Metric,b:&Metric,use_time:bool)->Result<bool>{if a.unwind!=b.unwind{return Ok(a.unwind)}if a.unwind{return Ok(a.gain>b.gain)}let same=use_time&&a.group.is_some()&&a.group==b.group;let da=mul(a.capital,if same{a.horizon.ok_or("ALLOCATION_HORIZON")? as i128}else{1})?;let db=mul(b.capital,if same{b.horizon.ok_or("ALLOCATION_HORIZON")? as i128}else{1})?;need(da>0&&db>0,"ALLOCATION_DENOMINATOR")?;Ok(mul(a.gain,db)?>mul(b.gain,da)?)}
/// Bounded in-memory scheduling fairness, never a physical order or retry log.
/// Keys are certificate+mode (not changing quote IDs); no unseen history assumed.
pub struct Fairness{wait:BTreeMap<String,u32>,last:Option<String>,maximum_wait:u32}
impl Fairness{pub fn new(maximum_wait:u32)->Result<Self>{need((1..=32).contains(&maximum_wait),"ALLOCATION_WAIT_BOUND")?;Ok(Self{wait:BTreeMap::new(),last:None,maximum_wait})}}
#[derive(Serialize)]pub struct Decision{pub selected_key:Option<String>,pub objective:Option<Objective>,pub fairness_override:bool,pub minimum_incremental_gain_units:Option<i128>,pub full_gross_funding_units:Option<i128>,pub source_sha256:Option<String>,pub review_sha256:Option<String>,pub deferred:BTreeMap<String,String>,pub execution_authority:bool}
fn choose(metrics:&[&Metric],heads:&[&Value],bank:&Session,b:&Budget,f:&mut Fairness,now:u64)->Result<(Option<usize>,Decision)>{b.current(bank,now)?;need(metrics.len()<=32&&heads.len()==metrics.len(),"ALLOCATION_CANDIDATE_BOUND")?;let mut keys=BTreeSet::new();let mut valid=vec![];let mut deferred=BTreeMap::new();for(i,m)in metrics.iter().enumerate(){need(keys.insert(m.key.clone())&&*heads[i]==b.head,"ALLOCATION_DUPLICATE_OR_HEAD")?;let reason=if m.expires<=now{Some("expired")}else if m.gain<=0{Some("nonpositive_incremental_value")}else if b.writes==0{Some("shared_write_budget")}else if m.gross>b.gross_cash{Some("full_gross_cash")}else if m.capital>b.committed_capacity{Some("committed_capacity")}else{None};if let Some(r)=reason{deferred.insert(m.key.clone(),r.into());}else{valid.push(i);}}
 f.wait.retain(|k,_|valid.iter().any(|i|&metrics[*i].key==k));for i in &valid{let n=f.wait.entry(metrics[*i].key.clone()).or_default();*n=n.saturating_add(1).min(32);}
 // Covered universal cash improvements have priority. Within that tier or the
 // funded-entry tier, rotate score ties and eventually serve eligible waiters.
 let unwind=valid.iter().any(|i|metrics[*i].unwind);valid.retain(|i|metrics[*i].unwind==unwind);valid.sort_by_key(|i|metrics[*i].key.clone());if let Some(last)=&f.last{let split=valid.iter().position(|i|metrics[*i].key>*last).unwrap_or(0);valid.rotate_left(split);}
 let time_comparable=valid.first().is_some_and(|i|metrics[*i].group.is_some()&&valid.iter().all(|j|metrics[*j].group==metrics[*i].group));
 let starved=valid.iter().copied().find(|i|f.wait[&metrics[*i].key]>=f.maximum_wait);let mut selected=starved;let fairness=starved.is_some();if selected.is_none(){for i in &valid{if let Some(old)=selected{if better(metrics[*i],metrics[old],time_comparable)?{selected=Some(*i)}}else{selected=Some(*i)}}}
 let mut d=Decision{selected_key:None,objective:None,fairness_override:fairness,minimum_incremental_gain_units:None,full_gross_funding_units:None,source_sha256:None,review_sha256:None,deferred,execution_authority:false};if let Some(i)=selected{let m=metrics[i];f.wait.insert(m.key.clone(),0);f.last=Some(m.key.clone());d.selected_key=Some(m.key.clone());d.objective=Some(if !m.unwind&&!time_comparable{Objective::CapitalEfficiencyOnly}else{m.objective()});d.minimum_incremental_gain_units=Some(m.gain);d.full_gross_funding_units=Some(m.gross);d.source_sha256=Some(m.source.clone());d.review_sha256=Some(m.review.clone());for j in &valid{if *j!=i{d.deferred.insert(metrics[*j].key.clone(),if metrics[*j].risk==m.risk{"overlapping_risk_group"}else{"one_physical_selection_per_pass"}.into());}}}Ok((selected,d))}
pub fn select_hints(bank:&Session,b:&Budget,f:&mut Fairness,hints:Vec<ReadHint>,now:u64)->Result<(Option<ReadHint>,Decision)>{let(i,d)=choose(&hints.iter().map(|h|&h.metric).collect::<Vec<_>>(),&hints.iter().map(|h|&h.head).collect::<Vec<_>>(),bank,b,f,now)?;Ok((i.and_then(|i|hints.into_iter().nth(i)),d))}
pub fn select_plans<'a>(bank:&Session,b:&Budget,f:&mut Fairness,plans:Vec<Eligible<'a>>,now:u64)->Result<(Option<Eligible<'a>>,Decision)>{let(i,d)=choose(&plans.iter().map(|h|&h.metric).collect::<Vec<_>>(),&plans.iter().map(|h|&h.head).collect::<Vec<_>>(),bank,b,f,now)?;Ok((i.and_then(|i|plans.into_iter().nth(i)),d))}
